  QuizQuestion(topic: "equilibrio", question: "Si K es muy grande, en el equilibrio predominan:", options: ["Los reactivos", "Los productos", "Las dos por igual", "Ninguna especie"], answer: 1, explanation: "K grande significa que la reacción está muy desplazada hacia productos.", difficulty: 2),
