  QuizQuestion(topic: "equilibrio", question: "Para la reacción A(g) ⇌ B(g) + C(g), al disminuir el volumen el equilibrio se desplaza hacia:", options: ["Productos (2 mol gas)", "Reactivos (1 mol gas)", "No se desplaza", "Depende de K"], answer: 1, explanation: "Menos volumen → más presión → lado con menos moles de gas, los reactivos.", difficulty: 3),
  QuizQuestion(topic: "equilibrio", question: "La tabla ICE sirve para:", options: ["Calcular el pH", "Organizar concentraciones inicial, cambio y equilibrio", "Medir la temperatura", "Ajustar ecuaciones"], answer: 1, explanation: "ICE = Inicial, Cambio, Equilibrio: ordena cualquier cálculo de equilibrio.", difficulty: 3),
  QuizQuestion(topic: "equilibrio", question: "¿Qué significa Q > K?", options: ["Faltan productos", "Sobra producto: avanza hacia reactivos", "Está en equilibrio", "K es cero"], answer: 1, explanation: "Q > K indica exceso de productos: la reacción neta va hacia reactivos.", difficulty: 1),
  QuizQuestion(topic: "equilibrio", question: "Al subir la temperatura en una reacción exotérmica, el equilibrio se desplaza hacia:", options: ["Productos", "Reactivos", "No cambia", "El catalizador"], answer: 1, explanation: "En una reacción exotérmica el calor es un producto: subir T desplaza hacia reactivos.", difficulty: 3),
  QuizQuestion(topic: "equilibrio", question: "Kc para aA + bB ⇌ cC + dD es:", options: ["[A][B]/[C][D]", "[C]ᶜ[D]ᵈ/[A]ᵃ[B]ᵇ", "[A]ᵃ[B]ᵇ/[C]ᶜ[D]ᵈ", "Kc = 1 siempre"], answer: 1, explanation: "Kc = productos elevados a sus coeficientes dividido entre reactivos elevados a los suyos.", difficulty: 3),
