  QuizQuestion(topic: "termo-cinetica", question: "La ΔHf° del O₂(g) en condiciones estándar es:", options: ["−249 kJ/mol", "0 kJ/mol", "+249 kJ/mol", "No está definida"], answer: 1, explanation: "Por definición, ΔHf° de un elemento en su forma estándar es 0.", difficulty: 2),
  QuizQuestion(topic: "termo-cinetica", question: "Si al duplicar [A] la velocidad se cuadruplica (con [B] constante), el orden respecto a A es:", options: ["0", "1", "2", "4"], answer: 2, explanation: "2ᵐ = 4 → m = 2: la velocidad depende de [A]².", difficulty: 2),
  QuizQuestion(topic: "termo-cinetica", question: "La vida media de una reacción de primer orden depende de:", options: ["La concentración inicial", "Solo de k", "Del tiempo transcurrido", "De la presión"], answer: 1, explanation: "t½ = ln 2 / k: para primer orden no depende de [A]₀.", difficulty: 2),
  QuizQuestion(topic: "termo-cinetica", question: "Una reacción con ΔH < 0 es:", options: ["Endotérmica", "Exotérmica", "Espontánea siempre", "Atermica"], answer: 1, explanation: "ΔH negativo significa que libera calor: exotérmica.", difficulty: 2),
  QuizQuestion(topic: "termo-cinetica", question: "La espontaneidad la decide:", options: ["ΔH solo", "ΔS solo", "ΔG = ΔH − TΔS", "La velocidad"], answer: 2, explanation: "ΔG < 0 → espontánea; ΔG combina entalpía y entropía.", difficulty: 3),
  QuizQuestion(topic: "termo-cinetica", question: "Si ΔH > 0 y ΔS > 0, la reacción es espontánea a:", options: ["Temperatura baja", "Temperatura alta", "Cualquier temperatura", "Nunca"], answer: 1, explanation: "ΔG = ΔH − TΔS: con T alta, el término −TΔS domina y ΔG se vuelve negativo.", difficulty: 3),
  QuizQuestion(topic: "termo-cinetica", question: "La energía de activación es:", options: ["La energía liberada", "La barrera mínima para que ocurra la reacción", "La entalpía total", "La velocidad inicial"], answer: 1, explanation: "Ea es la energía mínima que deben superar los reactivos para reaccionar.", difficulty: 2),
  QuizQuestion(topic: "termo-cinetica", question: "Al subir la temperatura, la velocidad de reacción normalmente:", options: ["Baja", "No cambia", "Aumenta", "Se hace cero"], answer: 2, explanation: "Más T → más moléculas superan Ea y más choques eficaces: k aumenta (Arrhenius).", difficulty: 3),
  QuizQuestion(topic: "termo-cinetica", question: "Un catalizador:", options: ["Se consume en la reacción", "Baja la energía de activación", "Cambia ΔH", "Cambia el equilibrio"], answer: 1, explanation: "El catalizador ofrece otro camino con menor Ea, sin consumirse ni cambiar ΔH o K.", difficulty: 2),
  QuizQuestion(topic: "termo-cinetica", question: "Para una reacción de primer orden, la gráfica de ln[A] frente a t es:", options: ["Una curva", "Una recta con pendiente −k", "Una recta con pendiente +k", "Una parábola"], answer: 1, explanation: "ln[A] = ln[A]₀ − kt: recta de pendiente −k.", difficulty: 2),
  QuizQuestion(topic: "termo-cinetica", question: "La ley de Hess dice que ΔH de una reacción:", options: ["Depende del camino", "Es la suma de los ΔH de los pasos", "Siempre es cero", "No se puede calcular"], answer: 1, explanation: "La entalpía es función de estado: ΔH total = suma de los pasos, sea cual sea el camino.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "¿Cuál es el símbolo del sodio?", options: ["So", "Na", "Sd", "N"], answer: 1, explanation: "El sodio es Na, del latín natrium.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "¿Cuál es el número atómico del carbono?", options: ["4", "6", "12", "14"], answer: 1, explanation: "El carbono tiene Z = 6: 6 protones.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "¿Qué elemento tiene el símbolo Fe?", options: ["Flúor", "Hierro", "Plomo", "Fósforo"], answer: 1, explanation: "Fe es el hierro, del latín ferrum.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "El helio es un:", options: ["Metal alcalino", "Halógeno", "Gas noble", "Metal de transición"], answer: 2, explanation: "He pertenece al grupo 18, los gases nobles.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "¿Cuál es el metal alcalino del periodo 3?", options: ["Mg", "Na", "K", "Ca"], answer: 1, explanation: "El grupo 1, periodo 3, es el sodio (Na).", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "¿Qué tienen en común los elementos de un mismo grupo?", options: ["Igual masa", "Igual número de electrones de valencia", "Igual periodo", "Igual número atómico"], answer: 1, explanation: "Los elementos de un grupo comparten configuración de valencia, por eso reaccionan parecido.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "El elemento con Z = 17 es:", options: ["Argón", "Cloro", "Azufre", "Flúor"], answer: 1, explanation: "Z = 17 es el cloro (Cl), un halógeno.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "¿Cuál es el elemento más ligero?", options: ["Helio", "Hidrógeno", "Litio", "Oxígeno"], answer: 1, explanation: "El hidrógeno (H, Z = 1) es el elemento más ligero.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "Los lantánidos se encuentran en el bloque:", options: ["s", "p", "d", "f"], answer: 3, explanation: "Los lantánidos (y actínidos) llenan los orbitales f.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "¿Qué elemento es un gas noble del periodo 2?", options: ["F", "Ne", "O", "N"], answer: 1, explanation: "El neón (Ne, Z = 10) es el gas noble del periodo 2.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "El oro tiene el símbolo:", options: ["Au", "Ag", "Or", "Go"], answer: 0, explanation: "Au viene del latín aurum.", difficulty: 1),
  QuizQuestion(topic: "tabla", question: "¿Cuántos protones tiene el oxígeno (Z = 8)?", options: ["6", "8", "16", "10"], answer: 1, explanation: "El número atómico Z es el número de protones: 8.", difficulty: 1),
  QuizQuestion(topic: "enlace", question: "Un enlace iónico se forma entre:", options: ["Dos no metales", "Un metal y un no metal", "Dos gases nobles", "Dos metales"], answer: 1, explanation: "El metal cede electrones y el no metal los acepta: atracción entre iones.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "El NaCl es un compuesto:", options: ["Covalente", "Iónico", "Metálico", "De hidrógeno"], answer: 1, explanation: "NaCl está formado por iones Na⁺ y Cl⁻ unidos por atracción electrostática.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "En el agua, el enlace O–H es:", options: ["Iónico", "Covalente polar", "Metálico", "De Van der Waals"], answer: 1, explanation: "O y H comparten electrones, pero el O atrae más el par: covalente polar.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "¿Qué molécula tiene geometría lineal?", options: ["H₂O", "CO₂", "NH₃", "CH₄"], answer: 1, explanation: "CO₂ es lineal (O=C=O, 180°), mientras H₂O es angular y NH₃ piramidal.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "El enlace de hidrógeno es más fuerte entre:", options: ["Dos alcanos", "Moléculas con O–H o N–H", "Dos gases nobles", "Dos metales"], answer: 1, explanation: "El puente de hidrógeno se da entre H unido a O, N o F y un par libre de otro átomo electronegativo.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "¿Cuál es la geometría del CH₄?", options: ["Lineal", "Plana", "Tetraédrica", "Piramidal"], answer: 2, explanation: "El metano tiene 4 pares enlazantes: geometría tetraédrica, ángulos de 109.5°.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "La electronegatividad mide:", options: ["La masa de un átomo", "La capacidad de un átomo de atraer electrones en un enlace", "El número de protones", "La energía de ionización"], answer: 1, explanation: "Es la tendencia de un átomo a atraer hacia sí los electrones del enlace.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "Un enlace covalente apolar se da entre:", options: ["Átomos con gran diferencia de electronegatividad", "Átomos iguales o con electronegatividad casi igual", "Un metal y un no metal", "Iones"], answer: 1, explanation: "Si la diferencia de electronegatividad es casi cero, el par se comparte por igual.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "¿Qué tipo de enlace mantiene unidos los átomos de un metal?", options: ["Iónico", "Covalente", "Metálico", "De hidrógeno"], answer: 2, explanation: "En el enlace metálico, los electrones de valencia forman un mar deslocalizado entre cationes.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "La molécula de NH₃ tiene geometría:", options: ["Tetraédrica", "Piramidal trigonal", "Lineal", "Plana triangular"], answer: 1, explanation: "NH₃ tiene 3 enlaces y un par libre: piramidal trigonal.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "¿Cuál tiene mayor punto de ebullición, H₂O o H₂S?", options: ["H₂S", "H₂O", "Igual", "Depende de la presión"], answer: 1, explanation: "El agua forma puentes de hidrógeno fuertes; el H₂S, no. Por eso hierve a 100 °C frente a −60 °C.", difficulty: 2),
  QuizQuestion(topic: "enlace", question: "En la teoría VSEPR, la geometría la decide:", options: ["La masa molar", "El número de pares de electrones alrededor del átomo central", "El color", "La temperatura"], answer: 1, explanation: "Los pares de electrones se repelen y se colocan lo más lejos posible entre sí.", difficulty: 2),
  // ---- Bachillerato: estequiometría básica ----
  QuizQuestion(topic: "bach-estequiometria", question: "¿Cuántos moles hay en 36 g de agua (H₂O, M = 18 g/mol)?", options: ["1 mol", "2 mol", "3 mol", "4 mol"], answer: 1, explanation: "n = m / M = 36 / 18 = 2 mol.", difficulty: 1),
  QuizQuestion(topic: "bach-estequiometria", question: "La masa molar del NaCl es aproximadamente:", options: ["58.5 g/mol", "35.5 g/mol", "23 g/mol", "94 g/mol"], answer: 0, explanation: "M(Na) + M(Cl) = 23 + 35.5 = 58.5 g/mol.", difficulty: 1),
  QuizQuestion(topic: "bach-estequiometria", question: "¿Cuántos átomos hay en 1 mol de hierro?", options: ["6.02 × 10²³", "1", "56", "6.02 × 10²²"], answer: 0, explanation: "Un mol contiene el número de Avogadro de partículas: 6.02 × 10²³.", difficulty: 1),
  QuizQuestion(topic: "bach-estequiometria", question: "¿Cuántos gramos son 0.5 mol de CO₂ (M = 44 g/mol)?", options: ["88 g", "44 g", "22 g", "11 g"], answer: 2, explanation: "m = n × M = 0.5 × 44 = 22 g.", difficulty: 1),
  QuizQuestion(topic: "bach-estequiometria", question: "En la reacción 2H₂ + O₂ → 2H₂O, ¿cuántos moles de agua se forman con 2 mol de H₂?", options: ["1 mol", "2 mol", "4 mol", "3 mol"], answer: 1, explanation: "La proporción es 2 mol H₂ : 2 mol H₂O, así que se forman 2 mol de agua.", difficulty: 1),
  QuizQuestion(topic: "bach-estequiometria", question: "¿Qué es un mol?", options: ["La masa de un átomo", "La cantidad de sustancia con 6.02 × 10²³ partículas", "Un litro de gas", "Un gramo de sustancia"], answer: 1, explanation: "El mol es la unidad de cantidad de sustancia: 6.02 × 10²³ partículas.", difficulty: 1),
  QuizQuestion(topic: "bach-estequiometria", question: "¿Cuántos moles hay en 8 g de H₂ (M = 2 g/mol)?", options: ["2 mol", "4 mol", "8 mol", "16 mol"], answer: 1, explanation: "n = 8 / 2 = 4 mol.", difficulty: 1),
  QuizQuestion(topic: "bach-estequiometria", question: "Para balancear C + O₂ → CO₂, el coeficiente de O₂ es:", options: ["1", "2", "3", "4"], answer: 0, explanation: "La ecuación ya está balanceada: 1 C y 2 O a cada lado.", difficulty: 1),
  // ---- Bachillerato: gases ----
  QuizQuestion(topic: "bach-gases", question: "En la ley de Boyle, si la presión se duplica a temperatura constante, el volumen:", options: ["Se duplica", "Se reduce a la mitad", "No cambia", "Se cuadruplica"], answer: 1, explanation: "P × V = constante: si P se duplica, V se reduce a la mitad.", difficulty: 1),
  QuizQuestion(topic: "bach-gases", question: "Un gas ocupa 2 L a 1 atm. A 2 atm (misma temperatura), ocupa:", options: ["1 L", "4 L", "2 L", "0.5 L"], answer: 0, explanation: "P₁V₁ = P₂V₂ → V₂ = 1 × 2 / 2 = 1 L.", difficulty: 1),
  QuizQuestion(topic: "bach-gases", question: "La ley de Charles relaciona:", options: ["Presión y volumen", "Volumen y temperatura", "Presión y temperatura", "Moles y volumen"], answer: 1, explanation: "A presión constante, V / T = constante.", difficulty: 1),
  QuizQuestion(topic: "bach-gases", question: "¿Cuántos litros ocupa 1 mol de gas ideal a TPE (0 °C y 1 atm)?", options: ["11.2 L", "22.4 L", "24 L", "44.8 L"], answer: 1, explanation: "El volumen molar a TPE es 22.4 L/mol.", difficulty: 1),
  QuizQuestion(topic: "bach-gases", question: "Si la temperatura absoluta se duplica a presión constante, el volumen:", options: ["Se duplica", "Se reduce a la mitad", "No cambia", "Se cuadruplica"], answer: 0, explanation: "Por la ley de Charles, V es proporcional a T.", difficulty: 1),
  QuizQuestion(topic: "bach-gases", question: "En PV = nRT, R vale aproximadamente:", options: ["0.082 L·atm/mol·K", "8.31 kJ/mol", "1.00", "273"], answer: 0, explanation: "R = 0.082 L·atm/(mol·K) = 8.31 J/(mol·K).", difficulty: 1),
  QuizQuestion(topic: "bach-gases", question: "Un gas a 300 K y 2 atm se calienta a 600 K (volumen constante). Su presión será:", options: ["1 atm", "2 atm", "4 atm", "8 atm"], answer: 2, explanation: "P es proporcional a T: al duplicar T, P se duplica a 4 atm.", difficulty: 1),
  QuizQuestion(topic: "bach-gases", question: "¿Qué gas se difunde más rápido, H₂ o O₂?", options: ["O₂", "H₂", "Igual", "Depende del recipiente"], answer: 1, explanation: "La difusión es más rápida cuanto menor es la masa molar: H₂ (2 g/mol) frente a O₂ (32 g/mol).", difficulty: 1),
  // ---- Bachillerato: disoluciones ----
  QuizQuestion(topic: "bach-disoluciones", question: "La molaridad es:", options: ["Moles de soluto por litro de disolución", "Gramos por litro", "Moles por kg de disolvente", "Litros por mol"], answer: 0, explanation: "M = n / V, en mol/L.", difficulty: 1),
  QuizQuestion(topic: "bach-disoluciones", question: "¿Cuántos moles hay en 500 mL de una disolución 2 M?", options: ["0.5 mol", "1 mol", "2 mol", "4 mol"], answer: 1, explanation: "n = M × V = 2 mol/L × 0.5 L = 1 mol.", difficulty: 1),
  QuizQuestion(topic: "bach-disoluciones", question: "Para preparar 1 L de disolución 1 M de NaCl se necesitan:", options: ["1 mol de NaCl", "1 g de NaCl", "58.5 L de NaCl", "1 L de NaCl"], answer: 0, explanation: "1 M × 1 L = 1 mol de soluto (58.5 g de NaCl).", difficulty: 1),
  QuizQuestion(topic: "bach-disoluciones", question: "Si se diluye una disolución hasta la mitad de su concentración, el volumen:", options: ["Se reduce a la mitad", "Se duplica", "No cambia", "Se cuadruplica"], answer: 1, explanation: "C₁V₁ = C₂V₂: si C se reduce a la mitad, V se duplica.", difficulty: 1),
  QuizQuestion(topic: "bach-disoluciones", question: "¿Qué masa de NaOH (M = 40 g/mol) hay en 2 L de disolución 0.5 M?", options: ["20 g", "40 g", "80 g", "10 g"], answer: 1, explanation: "n = 0.5 × 2 = 1 mol; m = 1 × 40 = 40 g.", difficulty: 1),
  QuizQuestion(topic: "bach-disoluciones", question: "Una disolución con 10 g de soluto en 100 g de disolución es:", options: ["10 % m/m", "10 M", "10 g/L", "1 % m/m"], answer: 0, explanation: "% m/m = (10 / 100) × 100 = 10 %.", difficulty: 1),
  QuizQuestion(topic: "bach-disoluciones", question: "Al añadir más disolvente a una disolución, su concentración:", options: ["Aumenta", "Disminuye", "No cambia", "Se hace cero"], answer: 1, explanation: "La misma cantidad de soluto queda en más volumen: la concentración baja.", difficulty: 1),
  QuizQuestion(topic: "bach-disoluciones", question: "¿Cuál es el disolvente universal?", options: ["El alcohol", "El agua", "El aceite", "El éter"], answer: 1, explanation: "El agua disuelve una gran cantidad de sustancias polares e iónicas.", difficulty: 1),
  // ---- Bachillerato: ácido-base ----
  QuizQuestion(topic: "bach-acido-base", question: "El pH de una disolución neutra a 25 °C es:", options: ["0", "7", "14", "1"], answer: 1, explanation: "A 25 °C el agua pura tiene [H⁺] = 10⁻⁷ M: pH = 7.", difficulty: 1),
  QuizQuestion(topic: "bach-acido-base", question: "Una disolución con pH = 3 es:", options: ["Básica", "Neutra", "Ácida", "Salina"], answer: 2, explanation: "pH < 7 indica disolución ácida.", difficulty: 1),
  QuizQuestion(topic: "bach-acido-base", question: "¿Cuál es un ácido fuerte?", options: ["Ácido acético", "HCl", "Ácido carbónico", "Amoniaco"], answer: 1, explanation: "El HCl se disocia por completo en agua; el acético y el carbónico son débiles.", difficulty: 1),
  QuizQuestion(topic: "bach-acido-base", question: "El pH de una disolución 0.01 M de HCl es:", options: ["1", "2", "3", "12"], answer: 1, explanation: "pH = −log(0.01) = 2.", difficulty: 1),
  QuizQuestion(topic: "bach-acido-base", question: "Una base tiene pH:", options: ["Menor que 7", "Igual a 7", "Mayor que 7", "Igual a 0"], answer: 2, explanation: "Las bases tienen [OH⁻] > [H⁺], así que pH > 7.", difficulty: 1),
  QuizQuestion(topic: "bach-acido-base", question: "La fenolftaleína en medio básico se vuelve:", options: ["Incolora", "Rosa", "Azul", "Amarilla"], answer: 1, explanation: "La fenolftaleína es incolora en ácido y rosa en medio básico.", difficulty: 1),
  QuizQuestion(topic: "bach-acido-base", question: "El pOH de una disolución con pH = 9 es:", options: ["9", "5", "14", "3"], answer: 1, explanation: "pH + pOH = 14, así que pOH = 5.", difficulty: 1),
  QuizQuestion(topic: "bach-acido-base", question: "Al mezclar un ácido con una base se produce:", options: ["Una oxidación", "Una neutralización", "Una precipitación", "Una combustión"], answer: 1, explanation: "Ácido + base → sal + agua: reacción de neutralización.", difficulty: 1),
  // ---- Universidad: química orgánica ----
  QuizQuestion(topic: "organica", question: "El grupo funcional −OH corresponde a:", options: ["Aldehído", "Alcohol", "Cetona", "Éter"], answer: 1, explanation: "El grupo hidroxilo −OH unido a un carbono es propio de los alcoholes.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El grupo funcional de los aldehídos es:", options: ["−COOH", "−CHO", "−CO−", "−NH₂"], answer: 1, explanation: "El aldehído es −CHO: un carbonilo en el extremo de la cadena.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "¿Qué sufijo tienen los alcanos?", options: ["−eno", "−ino", "−ano", "−ol"], answer: 2, explanation: "Alcanos: −ano (metano, etano); alquenos: −eno; alquinos: −ino; alcoholes: −ol.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El eteno (C₂H₄) es un:", options: ["Alcano", "Alqueno", "Alquino", "Alcohol"], answer: 1, explanation: "El eteno tiene un doble enlace C=C: es un alqueno.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El grupo carboxilo −COOH es propio de:", options: ["Ácidos carboxílicos", "Ésteres", "Aminas", "Alquenos"], answer: 0, explanation: "El grupo −COOH define a los ácidos carboxílicos.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "La fórmula general de los alcanos es:", options: ["CₙH₂ₙ", "CₙH₂ₙ₊₂", "CₙH₂ₙ₋₂", "CₙH₂ₙ₊₁"], answer: 1, explanation: "Los alcanos saturados siguen CₙH₂ₙ₊₂ (metano CH₄, etano C₂H₆).", difficulty: 3),
  QuizQuestion(topic: "organica", question: "Una reacción de adición típica es:", options: ["La adición de Br₂ a un alqueno", "La combustión", "La esterificación", "La deshidratación"], answer: 0, explanation: "El Br₂ se adiciona al doble enlace del alqueno y lo decolora: es la prueba de insaturación.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El benceno tiene:", options: ["Un anillo de 6 carbonos con enlaces deslocalizados", "Una cadena lineal", "Un triple enlace", "Un grupo OH"], answer: 0, explanation: "El benceno es un anillo aromático de 6 carbonos con 3 dobles enlaces deslocalizados.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "Los enantiómeros son:", options: ["Isómeros que son imágenes especulares no superponibles", "Isómeros cis y trans", "Alcanos ramificados", "Ácidos y bases conjugados"], answer: 0, explanation: "Como las manos izquierda y derecha: misma fórmula, distinta disposición espacial.", difficulty: 3),
  QuizQuestion(topic: "organica", question: "Un carbono quiral es aquel que tiene:", options: ["Cuatro sustituyentes diferentes", "Dos hidrógenos", "Un doble enlace", "Tres enlaces"], answer: 0, explanation: "Un carbono con 4 grupos distintos es un centro estereogénico.", difficulty: 3),
  QuizQuestion(topic: "organica", question: "La esterificación es la reacción entre:", options: ["Un ácido carboxílico y un alcohol", "Dos alcanos", "Un alqueno y agua", "Una amina y una cetona"], answer: 0, explanation: "Ácido carboxílico + alcohol → éster + agua.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El grupo funcional de las cetonas es:", options: ["−CHO", "−COOH", "−CO− (carbonilo entre dos carbonos)", "−O−"], answer: 2, explanation: "La cetona tiene el carbonilo C=O unido a dos carbonos (propanona).", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El etanol es:", options: ["Un aldehído", "Un alcohol", "Una cetona", "Un éter"], answer: 1, explanation: "El etanol (CH₃CH₂OH) es el alcohol del vino y la cerveza.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "La isomería cis/trans se da en:", options: ["Alcanos", "Alquenos con dos sustituyentes distintos en cada carbono del doble enlace", "Alquinos", "Ácidos carboxílicos"], answer: 1, explanation: "El doble enlace no gira, así que los sustituyentes quedan fijos a un lado u otro.", difficulty: 3),
  QuizQuestion(topic: "organica", question: "¿Cuál es un ejemplo de amida?", options: ["CH₃COOH", "CH₃CONH₂", "CH₃CH₂OH", "CH₃OCH₃"], answer: 1, explanation: "Las amidas tienen el grupo −CONH₂ (la etanamida es CH₃CONH₂).", difficulty: 1),
  // ---- Orgánica: grupos funcionales ----
  QuizQuestion(topic: "organica", question: "El grupo funcional −O− entre dos carbonos es propio de:", options: ["Éteres", "Alcoholes", "Aldehídos", "Ácidos carboxílicos"], answer: 0, explanation: "El éter tiene un oxígeno unido a dos carbonos (por ejemplo, CH₃−O−CH₃, dimetil éter).", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El grupo −NH₂ corresponde a:", options: ["Amida", "Amina", "Nitrilo", "Éster"], answer: 1, explanation: "El grupo amino −NH₂ define a las aminas (por ejemplo, la metilamina, CH₃NH₂).", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El grupo funcional −C≡N es propio de:", options: ["Nitrilos", "Alcoholes", "Alquenos", "Cetonas"], answer: 0, explanation: "El grupo ciano −C≡N define a los nitrilos (por ejemplo, CH₃−C≡N, etanonitrilo).", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El fenol es:", options: ["Un alcohol con −OH unido a un anillo bencénico", "Un aldehído aromático", "Un ácido carboxílico", "Un éter aromático"], answer: 0, explanation: "El fenol es C₆H₅−OH: el hidroxilo va unido directamente al anillo bencénico.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El CH₃Cl es un:", options: ["Alcohol", "Haluro de alquilo", "Éter", "Ácido"], answer: 1, explanation: "Un haluro de alquilo es un alcano con uno o más hidrógenos sustituidos por un halógeno (cloro, bromo…).", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El grupo funcional de los ésteres es:", options: ["−CHO", "−COOH", "−COO− (un carbonilo unido a un oxígeno)", "−O−"], answer: 2, explanation: "El éster es R−COO−R′: un carbonilo unido a un oxígeno que a su vez une otro carbono.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El grupo carbonilo C=O está presente en:", options: ["Aldehídos y cetonas", "Alcanos y alquenos", "Alcoholes y éteres", "Aminas y amidas"], answer: 0, explanation: "Aldehídos (−CHO) y cetonas (−CO−) comparten el carbonilo C=O; en las cetonas está entre dos carbonos y en los aldehídos en el extremo.", difficulty: 2),
  // ---- Orgánica: nomenclatura ----
  QuizQuestion(topic: "organica", question: "¿Cuántos carbonos tiene el butano?", options: ["2", "3", "4", "5"], answer: 2, explanation: "El prefijo but- indica 4 carbonos: CH₃CH₂CH₂CH₃.", difficulty: 1),
  QuizQuestion(topic: "organica", question: "El nombre IUPAC del CH₃CH₂OH es:", options: ["Metanol", "Etanol", "Propanol", "Ácido etanoico"], answer: 1, explanation: "Dos carbonos (et-) y grupo −OH (sufijo −ol): etanol.", difficulty: 1),
  QuizQuestion(topic: "organica", question: "El sufijo −oico indica:", options: ["Un aldehído", "Un alcohol", "Un ácido carboxílico", "Una cetona"], answer: 2, explanation: "Los ácidos carboxílicos se nombran con −oico: ácido etanoico, ácido propanoico.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El CH₃COOH se llama:", options: ["Ácido etanoico (ácido acético)", "Ácido metanoico", "Etanal", "Acetona"], answer: 0, explanation: "Dos carbonos con −COOH: ácido etanoico; su nombre común es ácido acético (el del vinagre).", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El nombre del CH₂=CH−CH₃ es:", options: ["Propano", "Propeno", "Propino", "Propanol"], answer: 1, explanation: "Tres carbonos con un doble enlace (sufijo −eno): propeno.", difficulty: 1),
  QuizQuestion(topic: "organica", question: "El 2-propanol es un alcohol:", options: ["Primario", "Secundario", "Terciario", "Cuaternario"], answer: 1, explanation: "El −OH está en el carbono 2, unido a otros dos carbonos: alcohol secundario (CH₃CH(OH)CH₃).", difficulty: 3),
  QuizQuestion(topic: "organica", question: "Al numerar la cadena principal se busca dar:", options: ["El número más alto al grupo funcional", "El localizador más bajo al grupo funcional principal", "El número más bajo al primer carbono", "El mismo número a todos los sustituyentes"], answer: 1, explanation: "La numeración se elige para que el grupo funcional principal quede con el localizador más bajo posible.", difficulty: 3),
  QuizQuestion(topic: "organica", question: "El metanal es:", options: ["La cetona más simple", "El aldehído más simple (formaldehído)", "El alcohol más simple", "El ácido más simple"], answer: 1, explanation: "El metanal (HCHO, formaldehído) es el aldehído de un solo carbono.", difficulty: 2),
  // ---- Orgánica: reacciones ----
  QuizQuestion(topic: "organica", question: "La combustión completa del metano produce:", options: ["CO y H₂", "CO₂ y H₂O", "C y H₂", "CO₂ y H₂"], answer: 1, explanation: "CH₄ + 2 O₂ → CO₂ + 2 H₂O: combustión completa con oxígeno suficiente.", difficulty: 1),
  QuizQuestion(topic: "organica", question: "En CH₃Cl + OH⁻ → CH₃OH + Cl⁻ ocurre una reacción de:", options: ["Adición", "Eliminación", "Sustitución", "Condensación"], answer: 2, explanation: "El OH⁻ sustituye al Cl: es una sustitución nucleofílica (el Cl sale y entra el OH).", difficulty: 2),
  QuizQuestion(topic: "organica", question: "Al deshidratar el etanol (con ácido y calor) se obtiene:", options: ["Etano", "Eteno", "Etanal", "Ácido acético"], answer: 1, explanation: "La deshidratación elimina H₂O del alcohol y forma el alqueno: CH₃CH₂OH → CH₂=CH₂ + H₂O.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "La hidrogenación de un alqueno produce:", options: ["Un alquino", "Un alcano", "Un alcohol", "Un aldehído"], answer: 1, explanation: "Añadir H₂ al doble enlace (con catalizador de Ni o Pt) lo convierte en enlace simple: el alqueno pasa a alcano.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "La oxidación suave del etanol da primero:", options: ["Ácido acético directamente", "Etanal, que se puede oxidar luego a ácido acético", "Eteno", "Metano"], answer: 1, explanation: "Alcohol primario → aldehído → ácido carboxílico: etanol → etanal → ácido etanoico.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "La polimerización del eteno produce:", options: ["Polietileno", "Poliestireno", "PVC", "Nailon"], answer: 0, explanation: "Muchas moléculas de eteno se unen en una cadena larga: el polietileno, el plástico más usado.", difficulty: 1),
  QuizQuestion(topic: "organica", question: "Al añadir HCl al propeno, según la regla de Markovnikov se obtiene sobre todo:", options: ["1-cloropropano", "2-cloropropano", "3-cloropropano", "Cloruro de alilo"], answer: 1, explanation: "El H se adiciona al carbono con más hidrógenos (C1) y el Cl al más sustituido (C2): 2-cloropropano.", difficulty: 3),
  QuizQuestion(topic: "organica", question: "La nitración del benceno es una reacción de:", options: ["Adición electrofílica", "Sustitución electrofílica aromática", "Eliminación", "Oxidación"], answer: 1, explanation: "El grupo −NO₂ sustituye un H del anillo y la aromaticidad se conserva: sustitución electrofílica aromática.", difficulty: 3),
  // ---- Orgánica: isomería y estereoquímica ----
  QuizQuestion(topic: "organica", question: "Dos isómeros tienen:", options: ["La misma fórmula molecular y distinta estructura", "Distinta fórmula molecular", "La misma estructura y distinto nombre", "Distinta masa molar"], answer: 0, explanation: "Isómeros: misma fórmula molecular (C₄H₁₀, por ejemplo) con los átomos conectados de forma distinta.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El butano y el metilpropano son:", options: ["El mismo compuesto", "Isómeros estructurales", "Enantiómeros", "Alótropos"], answer: 1, explanation: "Ambos son C₄H₁₀: uno de cadena lineal y el otro ramificado. Es isomería de cadena.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "Una molécula con 2 carbonos quirales distintos tiene como máximo:", options: ["2 estereoisómeros", "3 estereoisómeros", "4 estereoisómeros", "8 estereoisómeros"], answer: 2, explanation: "La regla es 2ⁿ: con n = 2 centros distintos, 2² = 4 estereoisómeros.", difficulty: 3),
  QuizQuestion(topic: "organica", question: "Una mezcla racémica:", options: ["Desvía la luz polarizada a la derecha", "Desvía la luz polarizada a la izquierda", "No desvía la luz polarizada", "Es siempre un líquido"], answer: 2, explanation: "Tiene la misma cantidad de los dos enantiómeros y sus giros se cancelan: no hay actividad óptica neta.", difficulty: 3),
  QuizQuestion(topic: "organica", question: "El ácido maleico y el ácido fumárico son isómeros:", options: ["Cis y trans, respectivamente", "Trans y cis, respectivamente", "Estructurales", "De posición"], answer: 0, explanation: "Ambos son HOOC−CH=CH−COOH: el maleico tiene los −COOH del mismo lado (cis) y el fumárico en lados opuestos (trans).", difficulty: 3),
  QuizQuestion(topic: "organica", question: "Los diastereómeros son estereoisómeros que:", options: ["Son imágenes especulares no superponibles", "No son imágenes especulares entre sí", "Tienen distinta fórmula molecular", "Son siempre aquirales"], answer: 1, explanation: "Los diastereómeros, como cis y trans, no son imágenes especulares: es el resto de la estereoisomería que no es enantiomería.", difficulty: 3),
  QuizQuestion(topic: "organica", question: "¿Cuál de estos alquenos presenta isomería cis/trans?", options: ["1-buteno", "2-buteno", "Propano", "Eteno"], answer: 1, explanation: "El 2-buteno tiene dos sustituyentes distintos en cada carbono del doble enlace; en el 1-buteno el C1 lleva dos H y no hay cis/trans.", difficulty: 3),
  // ---- Orgánica: obtención ----
  QuizQuestion(topic: "organica", question: "El etanol se obtiene por fermentación de la glucosa gracias a:", options: ["Las bacterias del ácido láctico", "Las levaduras", "La luz solar", "El oxígeno del aire"], answer: 1, explanation: "Las levaduras fermentan los azúcares: glucosa → etanol + CO₂.", difficulty: 1),
  QuizQuestion(topic: "organica", question: "La saponificación es la reacción de una grasa con:", options: ["Un ácido fuerte", "NaOH, que da jabón y glicerina", "Agua caliente sola", "Alcohol y calor"], answer: 1, explanation: "Grasa + hidróxido de sodio → jabón (sal de ácido graso) + glicerina. Así se hace el jabón.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "El craqueo del petróleo consiste en:", options: ["Quemar los alcanos", "Romper alcanos grandes en otros más pequeños (gasolina, gasóleo)", "Añadir hidrógeno a los alquenos", "Destilar el crudo"], answer: 1, explanation: "Con calor y catalizador, las cadenas largas se rompen en fracciones más útiles y con más demanda.", difficulty: 2),
  QuizQuestion(topic: "organica", question: "La destilación fraccionada del petróleo separa sus componentes por:", options: ["Su densidad", "Su punto de ebullición", "Su color", "Su solubilidad en agua"], answer: 1, explanation: "Cada fracción hierve a una temperatura distinta: los gases salen arriba y el fuelóleo queda abajo.", difficulty: 1),
  QuizQuestion(topic: "organica", question: "El eteno se puede obtener en el laboratorio:", options: ["Por combustión del etanol", "Por deshidratación del etanol con H₂SO₄ concentrado y calor", "Por fermentación de la glucosa", "Por saponificación de una grasa"], answer: 1, explanation: "Etanol + H₂SO₄ concentrado y calor → eteno + agua: es la eliminación de agua del alcohol.", difficulty: 2),
  // ---- Universidad: laboratorio (también es el cuestionario de laboratorio) ----
  QuizQuestion(topic: "laboratorio", question: "Antes de empezar una práctica hay que:", options: ["Leer el procedimiento y ponerse bata, guantes y gafas", "Probar los reactivos", "Calentar todo el material", "Abrir todos los frascos"], answer: 0, explanation: "La seguridad empieza por conocer el procedimiento y llevar el equipo de protección.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "Si un reactivo salpica a los ojos, se debe:", options: ["Frotarse los ojos", "Lavar con abundante agua en el lavaojos", "Esperar a que se seque", "Echarse alcohol"], answer: 1, explanation: "Lavaojos con agua abundante durante varios minutos y avisa al profesor.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "El material para medir volúmenes con mayor precisión es:", options: ["El vaso de precipitado", "La bureta", "El matraz Erlenmeyer", "La probeta"], answer: 1, explanation: "La bureta mide volúmenes con precisión de 0.05 mL; el vaso es lo menos preciso.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "Para preparar una disolución de concentración exacta se usa:", options: ["El matraz aforado", "El vaso de precipitado", "El tubo de ensayo", "La cápsula"], answer: 0, explanation: "El matraz aforado tiene un enrase exacto para un volumen fijo.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "El mechero Bunsen se usa para:", options: ["Medir masas", "Calentar", "Filtrar", "Pesar"], answer: 1, explanation: "Es la fuente de calor habitual del laboratorio.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "Nunca se debe:", options: ["Pipetear con la boca", "Etiquetar los frascos", "Usar guantes", "Anotar los datos"], answer: 0, explanation: "Siempre se pipetea con pera o pipeteador; con la boca se pueden aspirar reactivos tóxicos.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "La balanza analítica sirve para:", options: ["Medir volúmenes", "Medir masas con precisión de 0.0001 g", "Calentar muestras", "Medir el pH"], answer: 1, explanation: "La balanza analítica aprecia décimas de miligramo.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "El papel de filtro se usa en:", options: ["La destilación", "La filtración", "La titulación", "La centrifugación"], answer: 1, explanation: "La filtración separa un sólido de un líquido con el papel de filtro.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "En una titulación, el punto de equivalencia es cuando:", options: ["Se acaba el indicador", "Los moles de titulante igualan a los del analito", "La disolución hierve", "El pH es 0"], answer: 1, explanation: "En el punto de equivalencia se ha añadido la cantidad estequiométrica de titulante.", difficulty: 2),
  QuizQuestion(topic: "laboratorio", question: "El menisco se lee:", options: ["Por arriba", "Por la parte inferior, a la altura de los ojos", "De lado", "Por el borde del vaso"], answer: 1, explanation: "Se lee la parte inferior del menisco con el ojo a su altura para evitar el error de paralaje.", difficulty: 2),
  QuizQuestion(topic: "laboratorio", question: "Para diluir un ácido concentrado:", options: ["Se echa agua sobre el ácido", "Se echa el ácido sobre el agua, poco a poco", "Se mezclan de golpe", "Se calienta primero"], answer: 1, explanation: "Siempre el ácido sobre el agua: si se hace al revés, el agua puede hervir y salpicar ácido.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "El embudo de decantación sirve para:", options: ["Separar dos líquidos inmiscibles", "Filtrar sólidos", "Medir la temperatura", "Destilar"], answer: 0, explanation: "Separa dos fases líquidas por su diferente densidad (por ejemplo, agua y aceite).", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "La destilación separa mezclas por:", options: ["La densidad", "La diferencia de puntos de ebullición", "El color", "El tamaño de partícula"], answer: 1, explanation: "El componente más volátil se evapora primero y se condensa aparte.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "Un reactivo corrosivo lleva el pictograma de:", options: ["Una llama", "Un signo de exclamación", "Dos tubos derramando líquido sobre una mano", "Una calavera"], answer: 2, explanation: "El pictograma de corrosión (GHS05) muestra el líquido atacando una superficie y una mano.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "Los residuos químicos se desechan:", options: ["Por el fregadero", "En los contenedores específicos del laboratorio", "En la basura común", "Por la ventana"], answer: 1, explanation: "Cada residuo va a su contenedor; verterlos al fregadero contamina y puede ser peligroso.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "El tubo de ensayo se sostiene con:", options: ["La mano directamente", "Pinzas para tubos de ensayo", "Un imán", "Un trozo de papel"], answer: 1, explanation: "Las pinzas protegen la mano del calor y de salpicaduras.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "Al calentar un tubo de ensayo, la boca debe apuntar:", options: ["Hacia ti", "Hacia nadie, lejos de las personas", "Hacia el techo", "Hacia el mechero"], answer: 1, explanation: "El contenido puede salir proyectado al hervir: nunca apuntes a nadie.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "La probeta sirve para medir:", options: ["Masas", "Volúmenes aproximados de líquidos", "Temperaturas", "El pH"], answer: 1, explanation: "La probeta mide volúmenes con precisión intermedia, mayor que el vaso y menor que la bureta.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "¿Qué se hace con el material de vidrio roto?", options: ["Se tira a la basura común", "Se recoge con cuidado y se deposita en el contenedor de vidrio roto", "Se deja en la mesa", "Se guarda para repararlo"], answer: 1, explanation: "El vidrio roto va a su contenedor específico para no cortar a nadie.", difficulty: 1),
  QuizQuestion(topic: "laboratorio", question: "En el laboratorio, comer o beber está:", options: ["Permitido si es agua", "Prohibido", "Permitido solo en la mesa", "Permitido con guantes"], answer: 1, explanation: "Nada de comer ni beber: los reactivos pueden contaminar los alimentos.", difficulty: 1),
];

